 rdv=[("23 sept.","Indice PMI de la zone euro : l'activité des entreprises en septembre.","Source : S&P Global."),("24 sept.","Climat des affaires en France.","Source : Insee."),("29 oct.","Prochaine décision de la BCE sur ses taux.","Source : calendrier de la BCE.")],
